  "implementation": "def solve(case):
    # Validate payload structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ('round_scores', 'round_targets', 'forced'):
        if key not in case:
            raise ValueError(f"Missing required key: {key}")
    round_scores = case['round_scores']
    round_targets = case['round_targets']
    forced = case['forced']

    # Basic type checks
    if not isinstance(round_scores, list) or not isinstance(round_targets, list) or not isinstance(forced, list):
        raise ValueError("round_scores, round_targets, forced must be lists")
    if len(round_scores) != len(round_targets):
        raise ValueError("round_scores and round_targets must have same length")
    if len(round_scores) == 0:
        raise ValueError("at least one round required")

    n_tokens = len(round_scores[0])
    for scores in round_scores:
        if len(scores) != n_tokens:
            raise ValueError("All round_scores must have same length")
    for target in round_targets:
        if not isinstance(target, int) or target < 0:
            raise ValueError("round_targets must be non-negative integers")
    for idx in forced:
        if not isinstance(idx, int) or idx < 0 or idx >= n_tokens:
            raise ValueError(f"Invalid forced index: {idx}")
    forced_set = set(forced)

    # Initial active set: all indices (sorted original order)
    active = list(range(n_tokens))
    history = []

    for i, (scores, target) in enumerate(zip(round_scores, round_targets)):
        # Ensure forced indices are still active (they should be)
        if not forced_set.issubset(active):
            raise ValueError("Forced indices were pruned in previous round")
        if target < len(forced_set):
            raise ValueError(f"Round {i}: target {target} less than number of forced indices {len(forced_set)}")
        if target > len(active):
            raise ValueError(f"Round {i}: target {target} exceeds active count {len(active)}")

        # Candidates: active indices that are not forced
        candidates = [idx for idx in active if idx not in forced_set]
        # Sort by descending score, then by index for tie-breaking
        candidates_sorted = sorted(candidates, key=lambda idx: (-scores[idx], idx))

        # Number of slots to fill from candidates
        slots = target - len(forced_set)
        if slots > len(candidates):
            raise ValueError(f"Round {i}: not enough candidates (need {slots}, have {len(candidates)})")
        selected_candidates = candidates_sorted[:slots]

        # New active set: forced indices + selected, sorted by original index
        active = sorted(forced_set | set(selected_candidates))
        history.append(active[:])

    retained_indices = active[:]
    return {
        "history": history,
        "retained_indices": retained_indices
    }"
}
